import { openModal } from './dialog-service.js';
import HistoryDialog from '@/mobile/components/dialog/mobile-history-dialog.vue';

/**
 * 显示历史记录弹窗（用于未登录用户）
 * @param {Object} options 配置选项
 * @param {Function} options.onSignIn 用户点击登录按钮的回调函数
 * @param {Function} options.onClose 关闭弹窗的回调函数
 * @param {Object} options.data 传递给弹窗的数据
 * @param {Number} options.zIndex 层级
 */
export function showHistoryDialog(options = {}) {
  const {
    onSignIn = null,
    onClose = null,
    data = {},
    zIndex = 3000,
    ...otherOptions
  } = options;

  const dialogProps = {
    onSignIn,
    onClose,
    data,
    zIndex,
    ...otherOptions
  };

  return openModal(HistoryDialog, dialogProps);
}

/**
 * 显示未登录状态的历史记录弹窗
 * 提供快捷调用方法，用于未登录用户点击历史记录时显示
 * @param {Object} options 配置选项
 * @returns {Object} 弹窗控制对象
 */
export function showGuestHistoryDialog(options = {}) {
  return showHistoryDialog({
    data: {
      userType: 'guest',
      action: 'viewHistory'
    },
         onSignIn: (close, result) => {
       if (options.onSignIn) {
         options.onSignIn(close, result);
       } else {
         close();
       }
     },
    onClose: options.onClose,
    ...options
  });
} 