<template>
  <div class="mobile-navbar-container">
    <div class="mobile-navbar">
    <!-- 左侧区域 -->
    <div class="navbar-left">
      <!-- Logo -->
      <div v-if="isShowLogo" @click="clickLogo" class="logo-section">
        <mobile-l-img :src="logo" w="34px" h="34px" />
      </div>

      <!-- 历史按钮 -->
      <div v-if="isShowHistoryButton" @click="clickHistory" class="back-btn">
        <mobile-l-img src="/static/icon_history.png" w="35px" h="35px" />
      </div>
    </div>

    <!-- 中间区域 -->
    <div v-if="isShowCenter" class="navbar-center">
      <!-- 页面标题 -->
      <div @click="clickTitle" class="title-section">
        <span class="page-title">{{ currentModel }}</span>
        <mobile-l-img src="/static/images/mobile_navbar_arrow_down.png" w="24px" h="24px" />
      </div>
    </div>

    <!-- 右侧区域 -->
    <div class="navbar-right">
      <!-- 新建按钮 -->
      <div v-if="isShowAddChatButton" @click="clickAddChat" class="link-btn">
        <mobile-l-img src="/static/images/mobile_navbar_link.png" w="40px" h="40px" />
      </div>
      <!-- 历史按钮 -->
      <div v-if="isShowHistoryButton2" @click="clickHistory" class="back-btn">
        <mobile-l-img src="/static/icon_history.png" w="35px" h="35px" />
      </div>
      <!-- 登录按钮 -->
      <template v-if="isShowLoginBtn && isLoggedIn">
        <div @click="clickLogin" class="login-btn">
        <span>{{ $t('signIn') }}</span>
      </div>
      </template>
    </div>
    </div>
  </div>
</template>

<script setup>
import { ref, computed, onMounted, watch } from 'vue';
import { useRouter } from 'vue-router';
import { useI18n } from 'vue-i18n';
import { useUserStore } from '@/store/modules/user';
import { useAIChatStore } from '@/store/modules/AIChat';
import { useChatModelStore } from '@/store/modules/chat-model';
import { showModelSelector } from '@/utils/dialogMethod/model-selector-service.js';
import { showGuestHistoryDialog } from '@/utils/dialogMethod/history-dialog-service.js';
import { MODEL_CAPABILITIES } from '@/models/chat-model-models';
import { ROUTER_PATHS } from '@/router/constants';
import { routerReplace, routerToLogin, routerTo } from '@/router/navigation';
import MobileLImg from './../mobile-l-img.vue';

const userStore = useUserStore();
const aiChatStore = useAIChatStore();
const logo = ref(import.meta.env.VITE_APP_LOGO)


// 变量区域
const currentModel = ref('');
const isThinking = ref(false); // Think状态
const isSearchModeChoose = ref(false); // DeepSearch状态
const props = defineProps({
  isShowLogo: {
    type: Boolean,
    default: true
  },
  isShowHistoryButton: {
    type: Boolean,
    default: true
  },
  isShowAddChatButton: {
    type: Boolean,
    default: true
  },
  isShowHistoryButton2: {
    type: Boolean,
    default: true
  },
  isShowLoginBtn: {
    type: Boolean,
    default: true
  },
  isShowCenter: {
    type: Boolean,
    default: true
  }
})

const isLoggedIn = computed(() => !userStore.isLoggedIn);

// 计算属性区域
const modelType = computed(() => {
  return isThinking.value 
    ? MODEL_CAPABILITIES.REASONING 
    : isSearchModeChoose.value 
    ? MODEL_CAPABILITIES.DEEP_SEARCH 
    : MODEL_CAPABILITIES.TEXT;
});

// 点击事件区域
const clickTitle = () => {
  showModelSelector({
    type: modelType.value,
    initialSelected: currentModel.value,
    onConfirm: (close, selectedModel) => {
      console.log('用户选择了模型:', selectedModel);
      currentModel.value = selectedModel;
      
      // 仿照input-ai-chat的逻辑：更新aiChatStore中的模型信息
      const currentParams = aiChatStore.getAIChatParams() || {};
      aiChatStore.setAIChatParams({
        ...currentParams,
        model: selectedModel,
        isThinking: isThinking.value,
        enable_search: isSearchModeChoose.value
      });
      
      // 关闭弹窗
      close();
    }
  });
};

const clickLogo = () => {
  // Logo点击逻辑
  console.log('Logo clicked');
  routerReplace(ROUTER_PATHS.HOME)
};

const clickHistory = () => {
  // 历史按钮点击逻辑
  if (userStore.isLoggedIn) {
    // 已登录用户：跳转到会话历史页面
    routerTo(ROUTER_PATHS.CONVERSATION_HISTORY);
  } else {
    // 未登录用户：显示历史记录弹窗
    showGuestHistoryDialog({
      onSignIn: (close, result) => {
        close();
        routerToLogin();
      }
    });
  }
};

const clickLogin = () => {
  routerToLogin()
}

const clickAddChat = () => {
    routerTo(ROUTER_PATHS.HOME)
}

// 业务逻辑区域
const syncModelForCurrentType = async () => {
  // 当状态改变时，可能需要切换到该类型的默认模型
  // 例如：从TEXT模式切换到REASONING模式时，应该选择一个REASONING类型的模型
  try {
    const chatModelStore = useChatModelStore();
    let dataList = await chatModelStore.getTextModels();
    
    switch (modelType.value) {
      case MODEL_CAPABILITIES.TEXT:
        dataList = await chatModelStore.getTextModels();
        break;
      case MODEL_CAPABILITIES.REASONING:
        dataList = await chatModelStore.getReasoningModels();
        break;
      case MODEL_CAPABILITIES.DEEP_SEARCH:
        dataList = await chatModelStore.getDeepSearchModels();
        break;
    }
    
    if (dataList && dataList.length > 0) {
      // 检查当前模型是否在新的类型列表中
      const currentModelExists = dataList.some(model => model.name === currentModel.value);
      
      if (!currentModelExists) {
        // 如果当前模型不在新列表中，选择第一个模型
        const newModel = dataList[0].name;
        currentModel.value = newModel;
        
        // 更新store
        const currentParams = aiChatStore.getAIChatParams() || {};
        aiChatStore.setAIChatParams({
          ...currentParams,
          model: newModel,
          isThinking: isThinking.value,
          enable_search: isSearchModeChoose.value
        });
        
        console.log('自动切换模型:', newModel, '(类型:', modelType.value, ')');
      }
    }
  } catch (error) {
    console.error('同步模型失败:', error);
  }
};

// 初始化方法区域
const initFromStore = async () => {
  const chatParams = aiChatStore.getAIChatParams();
  if (chatParams) {
    // 从store中读取当前状态
    if (chatParams.model) {
      currentModel.value = chatParams.model;
    }else{
      await syncModelForCurrentType();
    }
    if (chatParams.isThinking !== undefined) {
      isThinking.value = chatParams.isThinking;
    }
    if (chatParams.enable_search !== undefined) {
      isSearchModeChoose.value = chatParams.enable_search;
    }
  }
};

// watch区域
// 监听modelType变化，当Think或Search状态改变时，自动切换到合适的模型
watch(modelType, async (newType, oldType) => {
  if (newType !== oldType) {
    console.log('模型类型改变:', oldType, '->', newType);
    // 当类型改变时，检查并同步模型
    await syncModelForCurrentType();
  }
});

// 监听store中的参数变化，实现双向同步
watch(() => aiChatStore.getAIChatParams(), (newParams) => {
  if (newParams) {
    // 从store同步状态到组件（避免外部修改store时不同步）
    if (newParams.model && newParams.model !== currentModel.value) {
      currentModel.value = newParams.model;
    }
    if (newParams.isThinking !== undefined && newParams.isThinking !== isThinking.value) {
      isThinking.value = newParams.isThinking;
    }
    if (newParams.enable_search !== undefined && newParams.enable_search !== isSearchModeChoose.value) {
      isSearchModeChoose.value = newParams.enable_search;
    }
  }
}, { deep: true });

// 周期函数区域
onMounted(() => {
  initFromStore();
});
</script>

