import { openModal } from './dialog-service.js';
import ModelSelectorDialog from '@/mobile/components/dialog/model-selector-dialog.vue';

/**
 * 显示模型选择弹窗
 * @param {Object} options 配置选项
 * @param {String} options.type 模型类型，来自MODEL_CAPABILITIES
 * @param {Array} options.items 直接传入的模型数组（可选）
 * @param {String} options.initialSelected 初始选择的模型名称
 * @param {Function} options.onConfirm 确认选择的回调函数
 * @param {Function} options.onCancel 取消选择的回调函数
 */
export function showModelSelector(options = {}) {
  const {
    type = null,
    items = [],
    initialSelected = null,
    onConfirm = null,
    onCancel = null,
    ...otherOptions
  } = options;

  const dialogProps = {
    type,
    items,
    initialSelected,
    onConfirm,
    onCancel,
    ...otherOptions
  };

  return openModal(ModelSelectorDialog, dialogProps);
} 